 function co(ticker, sectorNote){
   var b = FIN[ticker];
   if (!b) throw new Error("No FIN entry for ticker " + ticker);
   var note = [b.note, sectorNote].filter(Boolean).join("; ") || null;
   return Object.assign({}, b, {note: note});
 }

